fn main() {
    // Pulls the native Tiger Lake binary generated by build.rs
    const KERNEL_BINARY: &[u8] = include_bytes!(concat!(env!("OUT_DIR"), "/kernel_tgllp.bin"));

    unsafe {
        // 1. Initialize GPU Drivers
        let init_desc = ze_init_driver_desc_t {
            stype: ZE_STRUCTURE_TYPE_INIT_DRIVER_DESC,
            pNext: null(),
            flags: ZE_INIT_DRIVER_TYPE_FLAG_GPU,
        };
        let mut driver_count = 0;
        assert_eq!(zeInitDrivers(&mut driver_count, null_mut(), &init_desc), 0);
        assert!(driver_count > 0, "No Intel GPU drivers found");

        let mut drivers = vec![null_mut(); driver_count as usize];
        assert_eq!(
            zeInitDrivers(&mut driver_count, drivers.as_mut_ptr(), &init_desc),
            0
        );
        let primary_driver = drivers[0];

        // 2. Discover Physical Device
        let mut device_count = 0;
        assert_eq!(
            zeDeviceGet(primary_driver, &mut device_count, null_mut()),
            0
        );
        assert!(device_count > 0, "No Intel GPU devices found");

        let mut devices = vec![null_mut(); device_count as usize];
        assert_eq!(
            zeDeviceGet(primary_driver, &mut device_count, devices.as_mut_ptr()),
            0
        );
        let primary_device = devices[0];

        // 3. Query Device Properties
        let mut device_properties = ze_device_properties_t {
            stype: ZE_STRUCTURE_TYPE_DEVICE_PROPERTIES,
            pNext: null(),
            ..zeroed()
        };
        assert_eq!(
            zeDeviceGetProperties(primary_device, &mut device_properties),
            0
        );
        let device_name = CStr::from_ptr(device_properties.name.as_ptr()).to_string_lossy();
        println!(
            "Device: {} ({} MHz)",
            device_name, device_properties.coreClockRate
        );

        // 4. Find Compute Queue Group Ordinal
        let mut group_count = 0;
        assert_eq!(
            zeDeviceGetCommandQueueGroupProperties(primary_device, &mut group_count, null_mut()),
            0
        );
        let mut group_properties = vec![
            ze_command_queue_group_properties_t {
                stype: ZE_STRUCTURE_TYPE_COMMAND_QUEUE_GROUP_PROPERTIES,
                pNext: null(),
                ..zeroed()
            };
            group_count as usize
        ];
        assert_eq!(
            zeDeviceGetCommandQueueGroupProperties(
                primary_device,
                &mut group_count,
                group_properties.as_mut_ptr()
            ),
            0
        );
        let compute_ordinal = group_properties
            .iter()
            .position(|g| (g.flags & ZE_COMMAND_QUEUE_GROUP_PROPERTY_FLAG_COMPUTE) != 0)
            .expect("No compute queue group found") as u32;

        // 5. Create Context
        let context_desc = ze_context_desc_t {
            stype: ZE_STRUCTURE_TYPE_CONTEXT_DESC,
            pNext: null(),
            flags: 0,
        };
        let mut context = null_mut();
        assert_eq!(
            zeContextCreate(primary_driver, &context_desc, &mut context),
            0
        );

        // 6. Create Asynchronous In-Order Command Queue
        let queue_desc = ze_command_queue_desc_t {
            stype: ZE_STRUCTURE_TYPE_COMMAND_QUEUE_DESC,
            pNext: null(),
            ordinal: compute_ordinal,
            index: 0,
            flags: ZE_COMMAND_QUEUE_FLAG_IN_ORDER | ZE_COMMAND_QUEUE_FLAG_COPY_OFFLOAD_HINT,
            mode: ZE_COMMAND_QUEUE_MODE_ASYNCHRONOUS,
            priority: ZE_COMMAND_QUEUE_PRIORITY_NORMAL,
        };
        let mut command_queue = null_mut();
        assert_eq!(
            zeCommandQueueCreate(context, primary_device, &queue_desc, &mut command_queue),
            0
        );

        // 7. Create Command List
        let list_desc = ze_command_list_desc_t {
            stype: ZE_STRUCTURE_TYPE_COMMAND_LIST_DESC,
            pNext: null(),
            commandQueueGroupOrdinal: compute_ordinal,
            flags: ZE_COMMAND_LIST_FLAG_NONE,
        };
        let mut command_list = null_mut();
        assert_eq!(
            zeCommandListCreate(context, primary_device, &list_desc, &mut command_list),
            0
        );

        // 8. Allocate Unified Shared Memory (USM) & Populate on CPU
        let count: u32 = 16;
        let size_in_bytes = (count as usize) * size_of::<i32>();
        let device_mem_desc = ze_device_mem_alloc_desc_t {
            stype: ZE_STRUCTURE_TYPE_DEVICE_MEM_ALLOC_DESC,
            pNext: null(),
            flags: 0,
            ordinal: 0,
        };
        let host_mem_desc = ze_host_mem_alloc_desc_t {
            stype: ZE_STRUCTURE_TYPE_HOST_MEM_ALLOC_DESC,
            pNext: null(),
            flags: 0,
        };
        let mut shared_ptr: *mut c_void = null_mut();
        assert_eq!(
            zeMemAllocShared(
                context,
                &device_mem_desc,
                &host_mem_desc,
                size_in_bytes,
                64,
                primary_device,
                &mut shared_ptr,
            ),
            0
        );

        let slice = std::slice::from_raw_parts_mut(shared_ptr as *mut i32, count as usize);
        for i in 0..count as usize {
            slice[i] = i as i32;
        }

        // 9. Load Native Module & Extract Kernel
        let module_desc = ze_module_desc_t {
            stype: ZE_STRUCTURE_TYPE_MODULE_DESC,
            pNext: null(),
            format: ZE_MODULE_FORMAT_NATIVE,
            inputSize: KERNEL_BINARY.len(),
            pInputModule: KERNEL_BINARY.as_ptr(),
            pBuildFlags: null(),
            pConstants: null(),
        };
        let mut module = null_mut();
        assert_eq!(
            zeModuleCreate(
                context,
                primary_device,
                &module_desc,
                &mut module,
                null_mut()
            ),
            0
        );

        let kernel_name = CString::new("add_one").unwrap();
        let kernel_desc = ze_kernel_desc_t {
            stype: ZE_STRUCTURE_TYPE_KERNEL_DESC,
            pNext: null(),
            flags: 0,
            pKernelName: kernel_name.as_ptr(),
        };
        let mut kernel = null_mut();
        assert_eq!(zeKernelCreate(module, &kernel_desc, &mut kernel), 0);

        // 10. Configure Kernel Arguments, Work Groups & Dispatch
        assert_eq!(
            zeKernelSetArgumentValue(
                kernel,
                0,
                size_of::<*mut c_void>(),
                &shared_ptr as *const _ as *const c_void,
            ),
            0
        );

        let local_size = count.min(32);
        assert_eq!(zeKernelSetGroupSize(kernel, local_size, 1, 1), 0);

        let launch_args = ze_group_count_t {
            groupCountX: count.div_ceil(local_size),
            groupCountY: 1,
            groupCountZ: 1,
        };

        assert_eq!(
            zeCommandListAppendLaunchKernel(
                command_list,
                kernel,
                &launch_args,
                null_mut(),
                0,
                null_mut(),
            ),
            0
        );

        assert_eq!(zeCommandListClose(command_list), 0);
        assert_eq!(
            zeCommandQueueExecuteCommandLists(command_queue, 1, &command_list, null_mut()),
            0
        );
        assert_eq!(zeCommandQueueSynchronize(command_queue, u64::MAX), 0);

        // 11. Verify Results on CPU
        println!("Results:");
        println!("data    = {:?}", slice);

        // 12. Clean Up Resources
        assert_eq!(zeKernelDestroy(kernel), 0);
        assert_eq!(zeModuleDestroy(module), 0);
        assert_eq!(zeMemFree(context, shared_ptr), 0);
        assert_eq!(zeCommandListDestroy(command_list), 0);
        assert_eq!(zeCommandQueueDestroy(command_queue), 0);
        assert_eq!(zeContextDestroy(context), 0);
    }
}
